// Unified category tree (GET /categories). Demo mode: src/demo/category-tree.json + category-map.json, generated by
// apps/web/scripts/build-category-tree.mjs from the API's database/data/category_tree.json.
import type { MarketId, StoreMode } from "./types";

export type CatNode = {
  path: string;
  slug?: string;
  name: string;
  nameBn?: string | null;
  icon: string;
  /** cover photo: the admin's image or the category's best product (API); null = show the icon */
  image?: string | null;
  /** up to 4 cover photos */
  images?: string[] | null;
  depth: number;
  featured?: boolean;
  stores: MarketId[];
  count?: number;
  children: CatNode[];
};

export const PRICING_GROUPS = ["electronics", "fashion", "beauty", "grocery", "home"];

export function filterTree(nodes: CatNode[], store: StoreMode): CatNode[] {
  if (store === "all") return nodes;
  return nodes.filter((n) => n.stores.includes(store)).map((n) => ({ ...n, children: filterTree(n.children, store) }));
}

/** Node by path plus its ancestors (root first). */
export function findTrail(nodes: CatNode[], path: string): CatNode[] {
  for (const n of nodes) {
    if (n.path === path) return [n];
    if (path.startsWith(n.path + "/")) {
      const rest = findTrail(n.children, path);
      if (rest.length) return [n, ...rest];
    }
  }
  return [];
}
